async fn place_order(State(pool): State<PgPool>, Json(req): Json<PlaceOrder>) -> Result<Json<OrderId>, AppError> {
    let mut tx = pool.begin().await?;                     // dropped => rollback
    let available: i32 = sqlx::query_scalar("SELECT available FROM stock WHERE id = $1 FOR UPDATE")
        .bind(req.product_id).fetch_one(&mut *tx).await?;
    if available < req.qty { return Err(AppError::Conflict("insufficient stock")); }
    sqlx::query("UPDATE stock SET available = available - $1 WHERE id = $2")
        .bind(req.qty).bind(req.product_id).execute(&mut *tx).await?;
    let id: i64 = sqlx::query_scalar("INSERT INTO orders (product_id, qty) VALUES ($1, $2) RETURNING id")
        .bind(req.product_id).bind(req.qty).fetch_one(&mut *tx).await?;
    tx.commit().await?;                                  // last fallible step
    Ok(Json(OrderId(id)))
}
